  async function compilePrompt(){if(!app.prompt.intent.trim())throw Error('Add the intended outcome.');if(!app.currentTaskId){const created=await event('idea.create',{text:app.prompt.intent,title:app.prompt.intent.slice(0,80),context:currentContext()});app.currentTaskId=created.receipt?.id||created.receipt?.entityId||active(app.state.ideas).at(-1)?.id;}const invalid=lines(app.prompt.readPaths).filter(p=>!/^(Library|Foyer|Vaults)\//.test(p)||p.includes('..')||p.includes('\\'));if(invalid.length)throw Error('Read paths must be repository-relative Library, Foyer or Vaults paths. Role-reference paths remain separate.');const fields={intent:app.prompt.intent,context:app.prompt.context,output:app.prompt.output,role:app.prompt.role,constraints:app.prompt.constraints,roleReferences:jsonText(app.prompt.roleRefs||[]),readPaths:lines(app.prompt.readPaths),acceptance:lines(app.prompt.acceptance).join('\n')};const data=await api('/compile',{method:'POST',body:JSON.stringify({taskId:app.currentTaskId,fields,context:currentContext()})});acceptState(data);app.compiled=data;deferSave('ui:prompt',{fields:app.prompt,taskId:app.currentTaskId});renderPrompt();toast(data.readiness?.ready?'Compiled with a current dispatch receipt.':'Draft compiled; unresolved gates remain visible.');}
  async function dispatchJob(target){
    if(app.dispatchBusy)return;
    if(!app.compiled?.dispatch?.ready)throw Error('Compile and resolve readiness before handing off.');
    const fingerprint=app.compiled.dispatch.receiptId+':'+target;
    app.dispatchRequests??=new Map();
    if(!app.dispatchRequests.has(fingerprint))app.dispatchRequests.set(fingerprint,id());
    app.dispatchBusy=true;
    const button=$('#pb-dispatch');if(button)button.disabled=true;
    try{
      const data=await api('/jobs',{method:'POST',body:JSON.stringify({requestId:app.dispatchRequests.get(fingerprint),target,prompt:app.compiled.prompt,taskId:app.currentTaskId,context:{dispatchReceiptId:app.compiled.dispatch.receiptId}})});
      toast(data.status||'Server response received.');await refresh();renderPrompt();
      if(data.id||data.job?.id)await inspectJob(data.id||data.job.id);
    }finally{app.dispatchBusy=false;const current=$('#pb-dispatch');if(current)current.disabled=!app.compiled?.dispatch?.ready;}
  }
  async function inspectJob(jobId){const result=await api('/jobs/'+encodeURIComponent(jobId));const job=result.job||result;const pre=E('pre',jsonText(job),'pb-pre');const children=[pre,B('Refresh status',()=>inspectJob(jobId))];if(['running','accepted','starting'].includes(job.status))children.push(B('Cancel job',async()=>{const res=await api('/jobs/'+encodeURIComponent(jobId)+'/cancel',{method:'POST',body:JSON.stringify({requestId:id()})});toast(res.status||'Cancellation requested.');await inspectJob(jobId);}));dialog('Agent job',children);}
