  // Scan (founder 2026-10-12): a slim bar shows the real steps done of the steps total and their percentage, never a
  // made-up one; a short notice says what the scan found; the title bar keeps "Last scanned: YYYY-MM-DD HH:MM UTC".
  const SCAN_STEPS=['Reading source and local state','Checking chat models','Repainting the page'];
  function scanStamp(at){return at?'Last scanned: '+new Date(at).toISOString().slice(0,16).replace('T',' ')+' UTC':'Not scanned yet';}
  function scanProgress(done,total){return {pct:total?Math.round(done/total*100):0,text:done+' of '+total+' steps'};}
  function scanSummary(boot,providers){const cards=list(boot?.roadmap?.cards),open=cards.filter(c=>!c.sourceChecked).length,all=list(providers),ready=all.filter(p=>p.configured).length;return 'Scan complete: '+cards.length+' cards ('+open+' open), '+ready+' of '+all.length+' chat models ready.';}
  function showScan(done,total,step){const bar=$('#pb-scan'),label=$('#pb-scan-stamp'),p=scanProgress(done,total);if(bar){bar.hidden=false;bar.setAttribute('aria-valuenow',String(p.pct));bar.setAttribute('aria-valuetext',p.text+(step?': '+step:''));bar.firstChild.style.width=p.pct+'%';}if(label)label.textContent='Scanning: '+p.text+' ('+p.pct+'%)';}
  function markScanned(at){if(at!==undefined)app.scannedAt=at;const label=$('#pb-scan-stamp');if(label){label.textContent=scanStamp(app.scannedAt);label.title=label.textContent;}}
  async function scanNow(){if(app.scanning)return;app.scanning=true;const total=SCAN_STEPS.length;let ok=false;try{showScan(0,total,SCAN_STEPS[0]);status('Reading current source and local state…');await refresh({render:true});showScan(1,total,SCAN_STEPS[1]);await loadProviders();showScan(2,total,SCAN_STEPS[2]);renderDock();showScan(3,total);ok=true;status('Source and local state refreshed. Provider completion status is unchanged unless a real request completed.');}finally{app.scanning=false;const bar=$('#pb-scan');if(bar)setTimeout(()=>{bar.hidden=true;},ok?700:0);markScanned(ok?new Date():undefined);if(ok)toast(scanSummary(app.boot,app.providers),'ok');}}
  async function loadProviders(){try{const data=await api('/providers');app.providers=list(data.providers);}catch(error){app.providers=CHAT_PROVIDERS.map(provider=>({id:provider,name:CHAT_LABELS[provider],configured:false,status:'Status unavailable: '+error.message}));}}
  // The chat pane: "Chat", the page it is about and a compact model picker on the title line; then the thread;
